-- 简历工坊 · 模板/词库/meta 种子数据（从线上旧库导出，2026-09-18）
-- 幂等：可重复执行；已存在的按主键/唯一键更新。请在跑完 docs/schema.sql 之后执行本文件。
-- 内容：tpl_professions=30 行，tpl_glossary=56 行，tpl_meta=5 行

BEGIN;

-- 1) 职业模板
ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, industry=EXCLUDED.industry, summary=EXCLUDED.summary,
  sections=EXCLUDED.sections, sample=EXCLUDED.sample, theme=EXCLUDED.theme, sort=EXCLUDED.sort,
  updated_at=now();

-- 2) 职业词库（按 profession/kind/text 去重更新）
ON CONFLICT (profession,kind,md5(text)) DO UPDATE SET
  weight=EXCLUDED.weight, source=EXCLUDED.source, updated_at=now();

-- 3) 站点 meta（风格集/规模/版本等）
ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now();

COMMIT;
